import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(14))
G.add_edges_from([(4,5), (0,10), (2,7), (6,8), (2,8), (1,6), (0,9), (5,8)])
while True:
    degrees = [G.degree(node) for node in G.nodes]
    if all(3 = degree = 6 for degree in degrees):
        break
    for node in G.nodes:
        if G.degree(node) < 3:
            for other_node in G.nodes:
                if other_node != node and not G.has_edge(node, other_node):
                    G.add_edge(node, other_node)
                    break
        elif G.degree(node) > 6:
            for other_node in G.nodes:
                if other_node != node and G.has_edge(node, other_node):
                    G.remove_edge(node, other_node)
                    break
print(G.edges)
